                        for (int x = 0; x < image.width(); ++x)
                        {
                            const QColor color = image.pixelColor(x, y);
                            if (color.alpha() > 100
                                && color.red() > 220
                                && color.green() > 220
                                && color.blue() > 220)
                            {
                                return true;
                            }
                        }
