        bool soundHasActionsRow = false;
        if (soundTree)
        {
            for (int row = 0; row < soundTree->topLevelItemCount(); ++row)
            {
                QTreeWidgetItem* item = soundTree->topLevelItem(row);
                const QString label = item ? item->text(0).trimmed() : QString{};
                if (label == QStringLiteral("Sound"))
                {
                    soundGroupItem = item;
                }
                soundHasActionsRow = soundHasActionsRow || label == QStringLiteral("Actions");
            }
        }
        const std::size_t undoBeforeRemove = sectorSoundWindow.undoDepthForTest();
        const bool removeSoundWasIconOnly = removeSound
            && removeSound->toolButtonStyle() == Qt::ToolButtonIconOnly
            && !removeSound->icon().isNull();
        const bool removeWasInSoundHeader = removeSound != nullptr
            && soundGroupItem != nullptr
            && soundTree->itemWidget(soundGroupItem, 1) == removeSound->parentWidget();
        if (removeSound)
        {
            removeSound->click();
        }
        processEventsFor(5);
        const editor::DocumentState& removed = sectorSoundWindow.documentStateForTest();
        QToolButton* addSound = sectorSoundWindow.findChild<QToolButton*>(
            QStringLiteral("prop.sector.sound.add"));
        bool stillHasSoundGroup = false;
        soundTree = sectorSoundWindow.findChild<QTreeWidget*>(QStringLiteral("propertiesTree"));
        if (soundTree)
        {
            for (int row = 0; row < soundTree->topLevelItemCount(); ++row)
            {
                QTreeWidgetItem* item = soundTree->topLevelItem(row);
                stillHasSoundGroup = stillHasSoundGroup
                    || (item && item->text(0).trimmed() == QStringLiteral("Sound"));
            }
        }
        check(removeSoundWasIconOnly
                && removeWasInSoundHeader
                && !soundHasActionsRow
                && removed.level.sectors[0].sound.empty()
                && removed.level.sectors[1].sound.empty()
                && removed.level.sectors[0].soundVolume == 0.0
                && removed.level.sectors[1].soundVolume == 0.0
                && sectorSoundWindow.undoDepthForTest() == undoBeforeRemove + 1u
                && addSound && addSound->text() == QStringLiteral("Add Sound")
                && !stillHasSoundGroup
                && sectorSoundWindow.findChild<QLineEdit*>(
                    QStringLiteral("sectorSoundName")) == nullptr,
            "sector_sound Remove clears the selection and collapses its fields to Add Sound");
