        const auto* placementLayerField = window.findChild<QWidget*>(QStringLiteral("thingPlacementLayerField"));
        const auto* placementModeRow = window.findChild<QWidget*>(QStringLiteral("thingPlacementModeRow"));
        const auto* placementSnapRow = window.findChild<QWidget*>(QStringLiteral("thingPlacementSnapRow"));
