        if (viewportRenderThingsAction && viewportThingModeButton
            && viewportThingRenderingMenu && viewportCameraSettingsButton)
        {
            const bool renderThingsWasChecked = viewportRenderThingsAction->isChecked();
            viewportThingModeButton->click();
            QCoreApplication::processEvents();
            check(viewportThingModeButton->isChecked()
                    && !viewportThingRenderingMenu->isHidden()
                    && !viewportThingRenderingMenu->mask().isEmpty()
                    && !viewportThingRenderingMenu->mask().contains(QPoint(0, 0))
                    && viewportThingRenderingMenu->mask().contains(
                        viewportThingRenderingMenu->rect().center())
                    && viewportThingRenderingMenu->geometry().left() >= 0
                    && viewportThingRenderingMenu->geometry().top() >= 0
                    && viewportOverlay
                    && viewportThingRenderingMenu->geometry().top()
                        >= viewportOverlay->geometry().bottom() + 6,
                "main_window Thing rendering icon shows and anchors the persistent panel");

            const QImage thingPanelImage =
                viewportThingRenderingMenu->grab().toImage().convertToFormat(
                    QImage::Format_RGBA8888);
            const QColor intendedPanelFill(QStringLiteral("#15171c"));
            const auto colorNear = [](const QColor& lhs, const QColor& rhs)
            {
                return std::abs(lhs.red() - rhs.red()) <= 3
                    && std::abs(lhs.green() - rhs.green()) <= 3
                    && std::abs(lhs.blue() - rhs.blue()) <= 3
                    && lhs.alpha() >= 250;
            };
            const bool thingPanelHasSingleBorder = thingPanelImage.width() >= 7
                && thingPanelImage.height() >= 7
                && colorNear(
                    thingPanelImage.pixelColor(
                        thingPanelImage.width() - 3,
                        thingPanelImage.height() / 2),
                    intendedPanelFill)
                && colorNear(
                    thingPanelImage.pixelColor(
                        thingPanelImage.width() / 2,
                        thingPanelImage.height() - 3),
                    intendedPanelFill);
            check(thingPanelHasSingleBorder,
                "main_window Thing rendering paints panel fill immediately inside its right and bottom one-pixel border");

            const QPoint actionPoint =
                viewportThingRenderingMenu->actionGeometry(viewportRenderThingsAction).center();
            const QPoint actionGlobal = viewportThingRenderingMenu->mapToGlobal(actionPoint);
            QObject windowDispatchProxy;
            QMouseEvent windowDispatchPress(
                QEvent::MouseButtonPress,
                actionGlobal,
                actionGlobal,
                Qt::LeftButton,
                Qt::LeftButton,
                Qt::NoModifier);
            QApplication::sendEvent(&windowDispatchProxy, &windowDispatchPress);
            check(!viewportThingRenderingMenu->isHidden()
                    && viewportThingModeButton->isChecked(),
                "main_window Thing rendering treats window-level dispatch inside the panel as internal");

            QMouseEvent actionPress(
                QEvent::MouseButtonPress,
                actionPoint,
                actionGlobal,
                Qt::LeftButton,
                Qt::LeftButton,
                Qt::NoModifier);
            QMouseEvent actionRelease(
                QEvent::MouseButtonRelease,
                actionPoint,
                actionGlobal,
                Qt::LeftButton,
                Qt::NoButton,
                Qt::NoModifier);
            QApplication::sendEvent(viewportThingRenderingMenu, &actionPress);
            QApplication::sendEvent(viewportThingRenderingMenu, &actionRelease);
            QCoreApplication::processEvents();
            check(viewportRenderThingsAction->isChecked() != renderThingsWasChecked
                    && !viewportThingRenderingMenu->isHidden()
                    && viewportThingModeButton->isChecked(),
                "main_window Thing rendering remains open after changing an option");
            viewportRenderThingsAction->setChecked(renderThingsWasChecked);

            MousePressEater cameraPopupGuard;
            viewportCameraSettingsButton->installEventFilter(&cameraPopupGuard);
            const QPoint cameraPressPoint = viewportCameraSettingsButton->rect().center();
            const QPoint cameraPressGlobal =
                viewportCameraSettingsButton->mapToGlobal(cameraPressPoint);
            QMouseEvent cameraPress(
                QEvent::MouseButtonPress,
                cameraPressPoint,
                cameraPressGlobal,
                Qt::LeftButton,
                Qt::LeftButton,
                Qt::NoModifier);
            QApplication::sendEvent(viewportCameraSettingsButton, &cameraPress);
            QCoreApplication::processEvents();
            check(viewportThingRenderingMenu->isHidden()
                    && !viewportThingModeButton->isChecked(),
                "main_window clicking Camera Settings dismisses Thing rendering settings");

            viewportThingModeButton->click();
            QCoreApplication::processEvents();
            viewportThingModeButton->click();
            QCoreApplication::processEvents();
            check(viewportThingRenderingMenu->isHidden()
                    && !viewportThingModeButton->isChecked(),
                "main_window Thing rendering second icon click hides the panel");
        }
