            check(heldSettings.value(kGridSnapSetting, initiallyChecked).toBool() == initiallyChecked,
                "main_window held Grid Snap inversion does not change the persisted option");
            QKeyEvent ctrlRelease(QEvent::KeyRelease, Qt::Key_Control, Qt::NoModifier);
            window.eventFilterForTest(windowGlView, &ctrlRelease);
            check(transformGridSnapAction->isChecked() == initiallyChecked
                    && transformGridSnapButton->isChecked() == initiallyChecked
                    && thingMoveGridSnapButton->isChecked() == initiallyChecked
                    && addSectorGridSnapButton->isChecked() == initiallyChecked,
                "main_window held Grid Snap inversion restores every shared tool button on release");

            window.eventFilterForTest(windowGlView, &ctrlPress);
            QEvent deactivateEvent(QEvent::WindowDeactivate);
            window.eventFilterForTest(windowGlView, &deactivateEvent);
            check(transformGridSnapAction->isChecked() == initiallyChecked
                    && transformGridSnapButton->isChecked() == initiallyChecked
                    && thingMoveGridSnapButton->isChecked() == initiallyChecked
                    && addSectorGridSnapButton->isChecked() == initiallyChecked,
                "main_window deactivation clears a held Grid Snap preview when the key release occurs outside SED");

            QSettings restoreSettings = settingsStore();
            if (hadStoredGridSnap)
            {
                restoreSettings.setValue(kGridSnapSetting, storedGridSnap);
            }
            else
            {
                restoreSettings.remove(kGridSnapSetting);
            }
            restoreSettings.sync();
